    """
    Return appropriate dict based on result status.
    """
    status = result.get('status')
    if status == 'running':
        pid = result.get('process_id')
        if pid is None:
            raise ValueError("Missing process_id")
        return {
            "tool": "get_process_status",
            "process_id": pid
        }
    elif status == 'completed':
        exit_code = result.get('exit_code', 0)
        if exit_code == 0:
            return {
                "tool": "final_report",
                "success": True
            }
        else:
            return {
                "tool": "final_report",
                "success": False
            }
